package com.igrogram.app;

import android.app.Activity;
import android.os.Bundle;
import android.graphics.Color;
import android.graphics.Typeface;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import android.text.InputType;
import java.util.ArrayList;

public class MainActivity extends Activity {
    private final int blue=Color.rgb(40,145,230), ink=Color.rgb(28,37,48), muted=Color.rgb(130,145,158), bg=Color.rgb(245,247,249);
    private LinearLayout root, content; private final ArrayList<String> messages=new ArrayList<>();
    private TextView text(String s,int size,int color,boolean bold){ TextView t=new TextView(this); t.setText(s); t.setTextSize(size); t.setTextColor(color); if(bold)t.setTypeface(null,Typeface.BOLD); return t; }
    private GradientDrawableRound unused;
    @Override public void onCreate(Bundle b){ super.onCreate(b); getWindow().setStatusBarColor(blue); getWindow().setNavigationBarColor(Color.BLACK); showChats(); }
    private void base(String title,String subtitle){ root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setBackgroundColor(bg); setContentView(root); LinearLayout bar=new LinearLayout(this); bar.setGravity(Gravity.CENTER_VERTICAL); bar.setPadding(18,14,18,14); bar.setBackgroundColor(blue); TextView name=text(title,22,Color.WHITE,true); bar.addView(name,new LinearLayout.LayoutParams(0,-2,1)); if(subtitle!=null)bar.addView(text(subtitle,13,Color.WHITE,false)); root.addView(bar); content=new LinearLayout(this); content.setOrientation(LinearLayout.VERTICAL); root.addView(content,new LinearLayout.LayoutParams(-1,0,1)); }
    private void showChats(){ base("IGROgram","⋮"); content.setPadding(12,12,12,8); EditText search=new EditText(this); search.setSingleLine(true); search.setHint("Поиск"); search.setBackgroundColor(Color.WHITE); content.addView(search,new LinearLayout.LayoutParams(-1,52)); addChat("Александр","Привет! Как дела?","А", "12:41",true); addChat("Игровой чат","Кто сегодня играет?","И","11:58",false); addChat("Избранное","Сохранённые сообщения","★","Вчера",false); LinearLayout spacer=new LinearLayout(this); content.addView(spacer,new LinearLayout.LayoutParams(1,0,1)); TextView hint=text("Это первая версия IGROgram. Онлайн-чаты подключим после размещения сервера.",12,muted,false); hint.setGravity(Gravity.CENTER); content.addView(hint); bottomNav(); }
    private void addChat(String name,String last,String avatar,String time,boolean unread){ LinearLayout row=new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL); row.setPadding(8,14,8,14); TextView circle=text(avatar,22,Color.WHITE,true); circle.setGravity(Gravity.CENTER); circle.setBackground(new android.graphics.drawable.GradientDrawable(){ {setColor(blue);setShape(android.graphics.drawable.GradientDrawable.OVAL);} }); row.addView(circle,new LinearLayout.LayoutParams(52,52)); LinearLayout labels=new LinearLayout(this); labels.setOrientation(LinearLayout.VERTICAL); labels.setPadding(12,0,0,0); labels.addView(text(name,16,ink,true)); labels.addView(text(last,14,muted,false)); row.addView(labels,new LinearLayout.LayoutParams(0,-2,1)); LinearLayout right=new LinearLayout(this); right.setOrientation(LinearLayout.VERTICAL); right.setGravity(Gravity.RIGHT); right.addView(text(time,11,muted,false)); if(unread)right.addView(text("●",12,blue,true)); row.addView(right); row.setOnClickListener(v->showChat(name)); content.addView(row); View line=new View(this); line.setBackgroundColor(Color.rgb(229,233,237)); content.addView(line,new LinearLayout.LayoutParams(-1,1)); }
    private void bottomNav(){ LinearLayout nav=new LinearLayout(this); nav.setPadding(8,10,8,10); nav.setBackgroundColor(Color.WHITE); String[] items={"✉  Чаты","☏  Звонки","⚙  Настройки"}; for(String s:items){ TextView t=text(s,13,blue,true); t.setGravity(Gravity.CENTER); nav.addView(t,new LinearLayout.LayoutParams(0,48,1)); } root.addView(nav); }
    private void showChat(String name){ base(name,"⋮"); content.setPadding(12,12,12,12); TextView intro=text("Сообщения в этом чате появятся здесь",14,muted,false); intro.setGravity(Gravity.CENTER); content.addView(intro,new LinearLayout.LayoutParams(-1,0,1)); for(String m:messages){ TextView bubble=text(m,15,ink,false); bubble.setPadding(12,10,12,10); bubble.setBackground(new android.graphics.drawable.GradientDrawable(){ {setColor(Color.WHITE);setCornerRadius(22);} }); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2); p.gravity=Gravity.RIGHT; p.bottomMargin=8; content.addView(bubble,p); } LinearLayout send=new LinearLayout(this); send.setGravity(Gravity.CENTER_VERTICAL); EditText input=new EditText(this); input.setSingleLine(true); input.setHint("Сообщение"); input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES); send.addView(input,new LinearLayout.LayoutParams(0,52,1)); Button button=new Button(this); button.setText("➤"); button.setTextColor(Color.WHITE); button.setBackgroundTintList(android.content.res.ColorStateList.valueOf(blue)); send.addView(button); root.addView(send); button.setOnClickListener(v->{String s=input.getText().toString().trim(); if(!s.isEmpty()){messages.add(s); showChat(name);}}); }
    private static class GradientDrawableRound {}
}
